<?php
require_once __DIR__.'/includes/init.php';
$errors=[]; $sent=false;
if($_SERVER['REQUEST_METHOD']==='POST'){ require_csrf(); $name=trim((string)($_POST['name']??'')); $email=strtolower(trim((string)($_POST['email']??''))); $subject=trim((string)($_POST['subject']??'')); $message=trim((string)($_POST['message']??'')); if($name===''||!is_valid_email($email)||$message==='') $errors[]='Please complete all required fields.'; else { db_query('INSERT INTO contact_messages(name,email,subject,message) VALUES(?,?,?,?)',[$name,$email,$subject,$message]); $sent=true; } }
$pageTitle='Contact'; require __DIR__.'/includes/header.php'; ?><section class="container page-section"><p class="eyebrow">Get in touch</p><h1>Contact BFM</h1><?php if($sent): ?><div class="alert alert-success">Thanks. We will get back to you soon.</div><?php endif; ?><?php foreach($errors as $e): ?><div class="alert alert-error"><?=e($e)?></div><?php endforeach; ?><form method="post" class="form-stack" style="max-width:640px"><?=csrf_field()?><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Subject<input name="subject"></label><label>Message<textarea name="message" rows="6" required></textarea></label><button class="btn btn-primary">Send message</button></form></section><?php require __DIR__.'/includes/footer.php'; ?>
